questions.q:
Comment sortir d'une boucle LOOP quand une condition est vraie ?

- A. LEAVE condition;
- B. EXIT WHEN condition;
- C. STOP WHEN condition;
- D. BREAK IF condition;

questions.a:
CREATE OR REPLACE TRIGGER trg_consult_controle
BEFORE INSERT OR UPDATE ON consultation
FOR EACH ROW
BEGIN
  IF :NEW.montant IS NULL OR :NEW.montant < 0 THEN
    RAISE_APPLICATION_ERROR(-20101, 'Montant invalide');
  END IF;
  IF :NEW.statut = 'realisee' AND :NEW.date_consultation > SYSDATE THEN
    RAISE_APPLICATION_ERROR(-20102, 'Une consultation future ne peut pas etre realisee');
  END IF;
END;
/
- BEFORE ... FOR EACH ROW : contrôle des valeurs de :NEW avant l'écriture.

CREATE OR REPLACE FUNCTION nbconsultationspatient (p_id_patient IN NUMBER) RETURN NUMBER IS
  v_nb NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_nb FROM consultation
  WHERE id_patient = p_id_patient AND statut = 'realisee';
  RETURN v_nb;
END;
/
SELECT id_patient, nom, nbconsultationspatient(id_patient) FROM patient;

CREATE OR REPLACE PROCEDURE annulerconsultation (p_id IN NUMBER) IS
  v_statut consultation.statut%TYPE;
BEGIN
  SELECT statut INTO v_statut FROM consultation WHERE id_consultation = p_id;
  IF v_statut != 'prevue' THEN
    RAISE_APPLICATION_ERROR(-20103, 'Seule une consultation prevue peut etre annulee');
  END IF;
  UPDATE consultation SET statut = 'annulee' WHERE id_consultation = p_id;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RAISE_APPLICATION_ERROR(-20104, 'Consultation inexistante');
END annulerconsultation;
/
- SELECT ... INTO lit le statut ; NO_DATA_FOUND traduit l'inexistence en erreur applicative.
- Attention : le RAISE_APPLICATION_ERROR -20103 est levé dans le corps, pas dans la section EXCEPTION, donc NO_DATA_FOUND ne l'intercepte pas.
